package server

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"sync"
	"time"
)

// maxBufferedEvents caps a run's replayable event log. At ~1 bucket event per
// second this is over a day of run time — a backstop, not a working limit.
const maxBufferedEvents = 100_000

// event is one serialized SSE frame: a 1-based sequence number (the SSE id,
// which browsers echo back as Last-Event-ID on reconnect), a type, and its
// marshaled JSON payload.
type event struct {
	seq  int64
	name string
	data []byte
}

// eventLog is a run's append-only event history plus live fanout. Every event
// is retained (bounded by maxBufferedEvents), so a subscriber at any point —
// first open, late join, browser reconnect — is handled the same way: replay
// everything after its Last-Event-ID, then stream. That makes dropping a slow
// subscriber lossless: it reconnects and replays what it missed.
type eventLog struct {
	mu     sync.Mutex
	events []event
	subs   map[chan event]struct{}
	closed bool
}

func newEventLog() *eventLog {
	return &eventLog{subs: make(map[chan event]struct{})}
}

// emit marshals v, appends the event, and fans it out. A subscriber whose
// buffer is full is dropped (its channel closed) rather than blocking the
// coordinator; the SSE handler ends that response and the browser reconnects
// into a replay.
func (l *eventLog) emit(name string, v any) {
	data, err := json.Marshal(v)
	if err != nil {
		// A marshal failure is a programming error in an event payload; surface
		// it in-band rather than silently dropping the event.
		data = fmt.Appendf(nil, `{"error":"marshal: %s"}`, err)
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	// The cap bounds ONLY the bulk stream (one bucket event per second);
	// lifecycle events always land. They are O(levels + targets) — a handful
	// past the cap at most — and every consumer's correctness hangs on them:
	// dropping a level_start/level_result would let the race podium crown a
	// winner from an earlier level's data, and dropping run_done would leave
	// every viewer of a capped run reconnect-looping forever. Bucket loss
	// degrades gracefully (a gap in the replayed charts).
	if l.closed || (len(l.events) >= maxBufferedEvents && name == "bucket") {
		return
	}
	e := event{seq: int64(len(l.events)) + 1, name: name, data: data}
	l.events = append(l.events, e)
	for ch := range l.subs {
		select {
		case ch <- e:
		default:
			delete(l.subs, ch)
			close(ch)
		}
	}
}

// subscribe returns the replay of every event after seq `after`, plus a live
// channel (nil if the log is closed — the replay then already ends in the
// terminal event) and a cancel func.
func (l *eventLog) subscribe(after int64) ([]event, chan event, func()) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if after < 0 {
		after = 0 // a malformed/negative Last-Event-ID must not index the slice negatively
	}
	var replay []event
	if after < int64(len(l.events)) {
		replay = append(replay, l.events[after:]...)
	}
	if l.closed {
		return replay, nil, func() {}
	}
	ch := make(chan event, 256)
	l.subs[ch] = struct{}{}
	cancel := func() {
		l.mu.Lock()
		defer l.mu.Unlock()
		if _, ok := l.subs[ch]; ok {
			delete(l.subs, ch)
			close(ch)
		}
	}
	return replay, ch, cancel
}

// close ends the log after the terminal event has been emitted: live
// subscribers are closed out (their replay already delivered everything) and
// future subscribers get replay-only.
func (l *eventLog) close() {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.closed = true
	for ch := range l.subs {
		delete(l.subs, ch)
		close(ch)
	}
}

// serveSSE streams an eventLog as a Server-Sent-Events response: replay from
// the client's Last-Event-ID (or 0), then live events, with a comment
// heartbeat so proxies and the browser keep the connection alive.
func serveSSE(w http.ResponseWriter, r *http.Request, l *eventLog) {
	fl, ok := w.(http.Flusher)
	if !ok {
		http.Error(w, "streaming unsupported", http.StatusInternalServerError)
		return
	}
	var after int64
	if v := r.Header.Get("Last-Event-ID"); v != "" {
		after, _ = strconv.ParseInt(v, 10, 64)
	}

	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("X-Accel-Buffering", "no")
	w.WriteHeader(http.StatusOK)

	replay, ch, cancel := l.subscribe(after)
	defer cancel()
	for _, e := range replay {
		writeSSE(w, e)
	}
	fl.Flush()
	if ch == nil {
		return // run already finished; the replay ended in run_done
	}

	heartbeat := time.NewTicker(15 * time.Second)
	defer heartbeat.Stop()
	for {
		select {
		case e, ok := <-ch:
			if !ok {
				return // log closed (run finished) or we were dropped as slow
			}
			writeSSE(w, e)
			fl.Flush()
		case <-heartbeat.C:
			_, _ = fmt.Fprint(w, ": ping\n\n")
			fl.Flush()
		case <-r.Context().Done():
			return
		}
	}
}

func writeSSE(w http.ResponseWriter, e event) {
	_, _ = fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", e.seq, e.name, e.data)
}

package bench

import (
	"context"
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"time"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/config"
	gitclient "github.com/go-git/go-git/v6/plumbing/client"
	"github.com/go-git/go-git/v6/plumbing/transport"
	"github.com/go-git/go-git/v6/storage/memory"
)

// staleAfter is how old a run must be before its refs are swept. The run ID
// embeds its start time (base36 UnixNano), so this is a positive record of
// when the owning run began — refs younger than this belong to a run that
// could plausibly still be executing SOMEWHERE (another process or machine
// sharing the repo; within one server the active-run lock already
// serializes), and deleting a live run's refs would corrupt its
// measurements. Two overlapping generators on one repo+prefix corrupt each
// other's numbers regardless, so this guard is belt-and-braces for an
// unsupported setup; the cost is that refs from runs within the window
// linger until a later sweep, a few dozen refs at typical sweep sizes.
const staleAfter = 12 * time.Hour

// staleBenchRefRe matches exactly the refs forgemark itself pushes under a
// branch prefix, and nothing else: DestRef is
// refs/heads/<prefix><runID>-c<level>-a<agent>, run IDs are "fm"+base36
// UnixNano (12+ chars — the {8,} floor keeps a human branch like
// <prefix>fmt-c1-a1 out of range), the server inserts -t<target> into the run
// ID, and the session strategy appends -s<n> to the agent ref. Anything that
// doesn't match this shape is someone else's branch and must never be deleted.
// The capture group is the run ID's base36 timestamp, for the age guard.
func staleBenchRefRe(branchPrefix string) *regexp.Regexp {
	return regexp.MustCompile(`^refs/heads/` + regexp.QuoteMeta(branchPrefix) +
		`fm([0-9a-z]{8,})(-t[0-9]+)?-c[0-9]+-a[0-9]+(-s[0-9]+)?$`)
}

// staleRef reports whether ref is a forgemark bench ref whose owning run
// started before cutoff. A ref that matches the shape but carries an
// unparseable timestamp is NOT stale — when in doubt, never delete.
func staleRef(re *regexp.Regexp, ref string, cutoff time.Time) bool {
	m := re.FindStringSubmatch(ref)
	if m == nil {
		return false
	}
	nanos, err := strconv.ParseInt(m[1], 36, 64)
	if err != nil {
		return false
	}
	return time.Unix(0, nanos).Before(cutoff)
}

// CleanStaleBenchRefs deletes refs left behind by earlier forgemark runs from
// every repo this runner pushes to, and returns how many it deleted. Each
// run's refs embed its run ID, so they accumulate across runs; a growing ref
// advertisement inflates receive-pack negotiation and makes later
// measurements history-dependent. Running this inside the run — under the
// server's one-active-run rule — makes the deletion atomic with run
// registration on this server, and the staleAfter age guard (decoded from
// each ref's embedded run-start time) protects runs owned by OTHER processes
// or machines that this lock can't see. Only exact forgemark-shaped refs
// under this workload's branch prefix, from runs older than staleAfter, are
// touched.
func (r *Runner) CleanStaleBenchRefs(ctx context.Context) (int, error) {
	re := staleBenchRefRe(r.w.BranchPrefix)
	deleted := 0
	seen := map[string]bool{}
	for _, repoPath := range r.target.Repos {
		if seen[repoPath] {
			continue
		}
		seen[repoPath] = true
		n, err := r.cleanRepoRefs(ctx, repoPath, re)
		deleted += n
		if err != nil {
			return deleted, fmt.Errorf("clean stale bench refs in %s: %w", repoPath, err)
		}
	}
	return deleted, nil
}

func (r *Runner) cleanRepoRefs(ctx context.Context, repoPath string, re *regexp.Regexp) (int, error) {
	auth, err := r.creds.basicAuth(ctx, repoPath)
	if err != nil {
		return 0, err
	}
	opts := []gitclient.Option{gitclient.WithHTTPClient(r.httpc), gitclient.WithHTTPAuth(auth)}
	// nodes[0] serves the full advertisement and accepts ref deletes like any
	// push; per-node fan-out exists to spread load, not for correctness.
	remote := git.NewRemote(memory.NewStorage(memory.WithObjectFormat(r.ep.objFmt)), &config.RemoteConfig{
		Name: "origin", URLs: []string{verbatimURLFor(r.ep.nodes[0], repoPath)},
	})
	refs, err := remote.ListContext(ctx, &git.ListOptions{ClientOptions: opts})
	if errors.Is(err, transport.ErrEmptyRemoteRepository) {
		return 0, nil // nothing to clean in an unborn repo
	}
	if err != nil {
		return 0, fmt.Errorf("list refs: %w", err)
	}
	cutoff := time.Now().Add(-staleAfter)
	var specs []config.RefSpec
	for _, ref := range refs {
		if name := ref.Name().String(); staleRef(re, name, cutoff) {
			specs = append(specs, config.RefSpec(":"+name))
		}
	}
	if len(specs) == 0 {
		return 0, nil
	}
	// One push carries every deletion; an empty-source refspec needs no local
	// objects, so a bare remote over an empty storer suffices.
	err = remote.PushContext(ctx, &git.PushOptions{RemoteName: "origin", RefSpecs: specs, ClientOptions: opts})
	if err != nil && !errors.Is(err, git.NoErrAlreadyUpToDate) {
		return 0, fmt.Errorf("delete %d refs: %w", len(specs), err)
	}
	return len(specs), nil
}

