				case roll < d.errRate:
					s.Res = bench.OutcomeErr
					s.Msg = "demo: synthetic error"
				case roll < d.errRate+d.casRate && s.Op == bench.OpPush:
					s.Res = bench.OutcomeCAS // CAS is a ref-update outcome; clones can't CAS
				}
