package server

import (
	"context"
	"fmt"
	"math"
	"math/rand"
	"net/url"
	"strconv"
	"sync"
	"time"

	"github.com/entireio/forgemark/internal/bench"
)

// demoRunner synthesizes push samples so the whole pipeline — level barriers,
// collector, SSE, charts, persistence — can be exercised and demoed with no
// forge and no network. It is selected by a demo:// remote:
//
//	demo://fast?p50=80ms&spread=3&err=0.01&cas=0.02&cap=200
//
//	p50     median latency (Go duration; default 80ms)
//	spread  p99/p50 shape multiplier of the log-normal tail (default 3)
//	err     probability an op fails (default 0.01)
//	cas     probability an op is a CAS rejection (default 0)
//	cap     ops/sec saturation ceiling; approaching it inflates latency the
//	        way a real forge queues (default 0 = unbounded)
//
// Each concurrency level runs c goroutines that sleep a sampled latency per
// op, so throughput scales with concurrency until cap bends the curve — the
// same shapes a real sweep produces.
type demoRunner struct {
	label   string
	w       bench.Workload
	sink    bench.Sink
	p50     time.Duration
	sigma   float64 // log-normal shape derived from spread
	errRate float64
	casRate float64
	cap     float64
}

func isDemoRemote(remote string) bool {
	u, err := url.Parse(remote)
	return err == nil && u.Scheme == "demo"
}

func newDemoRunner(remote string, w bench.Workload, sink bench.Sink) (*demoRunner, error) {
	u, err := url.Parse(remote)
	if err != nil || u.Scheme != "demo" {
		return nil, fmt.Errorf("invalid demo remote %q", remote)
	}
	q := u.Query()
	d := &demoRunner{label: remote, w: w, sink: sink, p50: 80 * time.Millisecond, errRate: 0.01}
	spread := 3.0
	if v := q.Get("p50"); v != "" {
		if d.p50, err = time.ParseDuration(v); err != nil || d.p50 <= 0 {
			return nil, fmt.Errorf("demo: invalid p50 %q", v)
		}
	}
	for name, dst := range map[string]*float64{"spread": &spread, "err": &d.errRate, "cas": &d.casRate, "cap": &d.cap} {
		if v := q.Get(name); v != "" {
			f, err := strconv.ParseFloat(v, 64)
			// Reject NaN/±Inf explicitly: ParseFloat accepts them, and they pass a
			// bare `f < 0` check, then poison sigma/durations and can spin a tight
			// synthetic loop.
			if err != nil || math.IsNaN(f) || math.IsInf(f, 0) || f < 0 {
				return nil, fmt.Errorf("demo: invalid %s %q", name, v)
			}
			*dst = f
		}
	}
	if spread < 1 {
		return nil, fmt.Errorf("demo: spread must be >= 1")
	}
	// err and cas are probabilities per operation.
	if d.errRate > 1 || d.casRate > 1 {
		return nil, fmt.Errorf("demo: err and cas must be probabilities in [0,1]")
	}
	// Both outcomes resolve from one shared roll (bands [0,err) and
	// [err,err+cas)), so a sum over 1 would silently clip the CAS band — e.g.
	// err=0.8&cas=0.8 would yield only ~0.2 CAS instead of the requested 0.8.
	if d.errRate+d.casRate > 1 {
		return nil, fmt.Errorf("demo: err + cas must not exceed 1 (each op resolves one shared probability roll)")
	}
	// For a log-normal around the median, p99 = median * exp(sigma * z99).
	d.sigma = math.Log(spread) / 2.326
	return d, nil
}

func (d *demoRunner) Label() string        { return d.label }
func (d *demoRunner) Nodes() int           { return 1 }
func (d *demoRunner) ObjectFormat() string { return "sha1" }

// nextOp mirrors the real strategies' op mix so demo buckets exercise the
// same consumer paths: clone strategy emits only clones; session emits one
// clone and then, ONLY if that clone succeeded, SessionCommits pushes before
// the next clone — a real session agent retries the clone immediately after
// a clone failure (runSessions' `continue`), so an error-heavy demo must not
// publish pushes against a session that never cloned. pushesLeft is the
// agent's session state: how many pushes remain in its current session.
func (d *demoRunner) nextOp(pushesLeft int) bench.OpKind {
	switch d.w.Strategy {
	case "clone":
		return bench.OpClone
	case "session":
		if pushesLeft == 0 {
			return bench.OpClone
		}
	}
	return bench.OpPush
}

// demoAgg folds a level's synthetic samples into bounded state as they are
// produced, instead of retaining them for an end-of-level summarize: at the
// supported envelope (4096 agents × the 1ms latency floor × a long level,
// times up to 8 targets) retained samples reach millions per second and OOM
// the server. Counters plus two fixed-size histograms (~2KB) carry everything
// LevelResult needs; percentiles come out with the histogram's ~6.7% bucket
// resolution, which is indistinguishable on a chart of synthetic data.
type demoAgg struct {
	mu              sync.Mutex
	warmup          time.Duration
	pushes, ok, cas int
	errs            int
	clones, cloneOK int
	cloneErrs       int
	lat, cloneLat   latHist
}

func (a *demoAgg) add(s bench.Sample) {
	if s.Offset < a.warmup {
		return // warm-up: excluded from every statistic, like summarize
	}
	idx := latHistIdx(float64(s.Dur) / float64(time.Millisecond))
	a.mu.Lock()
	defer a.mu.Unlock()
	if s.Op == bench.OpClone {
		a.clones++
		if s.Res == bench.OutcomeOK {
			a.cloneOK++
			a.cloneLat[idx]++
		} else {
			a.cloneErrs++
		}
		return
	}
	a.pushes++
	switch s.Res {
	case bench.OutcomeOK:

// don't append zero/stale buckets to the timeline. The end-of-level flush calls
// it with force=true to emit the window's final partial second even though the
// window has just closed.
//
// Invariant: every emitted bucket carries dt_ms >= 1 and a t inside its
// level's window. Consumers read dt_ms 0/absent as a legacy ~1s bucket
// (bucketSecs in charts.js), so a zero must never be emitted, and the tail
// flush must be stamped at the second the window closed — not at emission
// time, which for the session strategy trails the window by up to 30s of
// ref cleanup and would plot the tail deep in the between-level gap.
func (r *Run) emitBucket(force bool) {
	// Hold r.mu across the whole tick so a level transition (which resets the
	// collectors and advances levelIdx under the same lock) can't interleave:
	// otherwise a snapshot could carry the previous level's samples under the
	// new level index. The snapshot and series append are cheap and run once
	// per second. Lock order is always r.mu → collector.mu, never reversed.
	r.mu.Lock()
	defer r.mu.Unlock()
	// A bucket's OK count spans the interval since the previous bucket, which is
	// only ~1s for a steady tick but is fractional for the first tick after the
	// warm-up boundary and for the forced tail flush. Carry the bucket's actual
	// measured duration so consumers plot count/duration (a true rate) instead of
	// treating the raw count as ops/s. dt is the overlap of (lastBucketAt, now]
	// with the measured window [windowStart+warmup, +duration], so warm-up-only
	// buckets get 0 and the tail gets only its real remainder.
	wallNow := time.Now()
	measStart := r.windowStart.Add(r.bw.Warmup)
	measEnd := measStart.Add(r.bw.Duration)
	// A periodic tick emits only inside an open window. measuring stays true
	// through RunLevel's post-window session-ref cleanup (up to 30s), so also
	// gate on the deadline: past measEnd the ticks are cleanup-time buckets with
	// zero duration and stale percentiles, which consumers would misread. The
	// forced tail flush (force=true) still emits the window's real remainder.
	// A cancelled run closes the window immediately, whatever the wall clock:
	// agents stop at cancel, but session cleanup keeps lwg (and therefore
	// measuring) alive for up to 30s, during which mid-window ticks would
	// publish zero-count buckets with stale percentiles and positive dt.
	if !force && (!r.measuring || r.ctx.Err() != nil || wallNow.After(measEnd)) {
		return
	}
	lo, hi := r.lastBucketAt, wallNow
	if lo.Before(measStart) {
		lo = measStart
	}
	if hi.After(measEnd) {
		hi = measEnd
	}
	// Round a positive overlap UP to a whole millisecond, never truncate: every
	// consumer reads dt_ms 0/absent as the ~1s legacy fallback, so a real
	// sub-millisecond overlap truncated to 0 would understate that bucket's
	// rate by up to 1000×. Ceiling instead overstates the sliver by <1ms.
	dtMs := int64(0)
	if d := hi.Sub(lo); d > 0 {
		dtMs = int64((d + time.Millisecond - 1) / time.Millisecond)
	}
	r.lastBucketAt = wallNow
	if dtMs == 0 {
		// Zero overlap means nothing measured happened in this tick — a warm-up
		// second, typically. dt_ms 0 is dropped by omitempty on persist, and every
		// consumer reads absent as a legacy ~1s bucket, so emitting it would add a
		// phantom second to any (t, level) slot the replay merges it into and
		// understate the replayed rate. Skip periodic ticks outright; a forced
		// tail flush may still carry boundary-sliver completions, so emit those
		// under a 1ms floor rather than an ambiguous zero.
		if !force {
			return
		}
		dtMs = 1
	}
	// Stamp the bucket at the end of the interval it covers. For a periodic
	// tick hi is wallNow, so nothing changes; for the tail flush hi is clamped
	// to the window end, which is where its samples belong. History replay
	// merges a flush that shares the final tick's whole second by design.
	now := hi.Unix()

	li, c := r.levelIdx, r.levelConc
	stats := make(map[string]BucketStats, len(r.targets))
	for _, t := range r.targets {
		if t.dead {
			continue
		}
		st := t.col.snapshot()
		stats[strconv.Itoa(t.id)] = st
		if len(t.series) < maxBufferedEvents {
			t.series = append(t.series, results.SeriesPoint{
				T: now, DtMs: dtMs, Level: li, OK: st.OK, CAS: st.CAS, Err: st.Err,
				P50: st.P50, P95: st.P95, P99: st.P99,
				CloneOK: st.CloneOK, CloneErr: st.CloneErr,
				CloneP50: st.CloneP50, CloneP95: st.CloneP95, CloneP99: st.CloneP99,
			})
		}
	}
	if len(stats) == 0 {
		return
	}
	r.log.emit("bucket", map[string]any{
		"level_index": li, "concurrency": c, "t": now, "dt_ms": dtMs, "targets": stats,
	})
}

func (r *Run) markDead(t *targetState, levelIdx int, err error) {
	r.mu.Lock()
	t.dead = true
	t.fatalErr = err.Error()
	r.mu.Unlock()
	r.log.emit("target_error", map[string]any{
		"target": t.id, "level_index": levelIdx, "message": err.Error(), "fatal": true,
	})
}

