1	// Live run dashboard. All state derives from the SSE event stream — a fresh
2	// page load, a late join, and a mid-run reconnect are the same code path
3	// (server replays from Last-Event-ID).
4	
5	import { h } from '../dom.js';
6	import { api } from '../api.js';
7	import { openRunStream } from '../sse.js';
8	import { timeChart, targetColor, fmtNum, fmtMs, bucketSecs } from '../charts.js';
9	import { levelCountdown, resultsSavedBanner } from './shared.js';
10	
11	export function renderDashboard(app, runId) {
12	  const state = {
13	    hello: null,
14	    strategy: '',
15	    warmups: [],      // [{from, to}] unix-sec ranges for shading
16	    latRows: [],      // [ts, ...per-target {p50,p95,p99}] for percentile switching
17	    totals: {},       // per target id: {ok, cas, err, lastOps, p95}
18	    curLevel: null,   // latest level_start payload
19	    done: null,
20	  };
21	  let charts = {};
22	  let es = null;
23	  let ticker = null;
24	  let pct = 'p95';
25	
26	  // --- static skeleton ---
27	  const badge = h('span', { class: 'badge running' }, 'connecting…');
28	  const cancelBtn = h('button', { class: 'danger small', style: { display: 'none' }, onclick: async () => {
29	    cancelBtn.disabled = true;
30	    try { await api.cancelRun(runId); } catch { cancelBtn.disabled = false; }
31	  } }, 'Cancel run');
32	  const workloadNote = h('span', { class: 'progress-note' });
33	  const levelsStrip = h('div', { class: 'levels-strip' });
34	  const banners = h('div');
35	  const tiles = h('div', { class: 'tiles' });
36	  const chartsBox = h('div');
37	  const resultsBox = h('div');
38	
39	  app.append(
40	    h('div', { class: 'run-head' },
41	      h('h1', {}, `Run ${runId}`), badge, workloadNote, h('span', { class: 'spacer' }),
42	      h('a', { class: 'race-alt', href: `#race/${runId}` }, '⚡ race view'), cancelBtn),
43	    banners, levelsStrip, tiles, chartsBox, resultsBox);
44	
45	  const warned = sessionStorage.getItem(`fm-warn-${runId}`);
46	  if (warned) {
47	    for (const wtext of JSON.parse(warned)) banners.append(h('div', { class: 'banner warn' }, '⚠ ' + wtext));
48	  }
49	
50	  // --- charts are built once targets are known (hello) ---
51	  function buildCharts(targets) {
52	    const isClone = state.strategy === 'clone';
53	    const isSession = state.strategy === 'session';
54	    const bands = () => state.warmups;
55	
56	    const mk = (title, note, opts) => {
57	      const el = h('div');
58	      const head = h('div', { class: 'chart-head' }, h('h2', {}, title), note ? h('span', { class: 'u-note' }, note) : null);
59	      const card = h('div', { class: 'card chart-card' }, head, el);
60	      chartsBox.append(card);
61	      return { el, head, chart: timeChart(el, opts) };
62	    };
63	
64	    const tputSeries = targets.map((t) => ({ label: t.name, color: targetColor(t.id) }));
65	    if (isSession) {
66	      for (const t of targets) tputSeries.push({ label: `${t.name} clones`, color: targetColor(t.id), dash: [5, 5] });
67	    }
68	    charts.tput = mk(isClone ? 'Clone throughput' : 'Push throughput',
69	      isClone ? 'successful clones per second' : 'successful pushes per second' + (isSession ? ' · dashed = clones/s' : ''),
70	      { series: tputSeries, unit: fmtNum, bands }).chart;
71	
72	    // Session interleaves two op streams with very different timings; a chart
73	    // labeled plain "Latency" that silently showed only pushes would present
74	    // half the workload as the whole. Clones get their own dashed series.
75	    const latSeries = targets.map((t) => ({ label: t.name, color: targetColor(t.id) }));
76	    if (isSession) {
77	      for (const t of targets) latSeries.push({ label: `${t.name} clones`, color: targetColor(t.id), dash: [5, 5] });
78	    }
79	    const latHead = mk('Latency', `rolling 10s window · shaded = warm-up${isSession ? ' · dashed = clones' : ''}`, {
80	      series: latSeries,
81	      unit: fmtMs, bands,
82	    });
83	    charts.lat = latHead.chart;
84	    const seg = h('div', { class: 'seg' }, ['p50', 'p95', 'p99'].map((p) =>
85	      h('button', { type: 'button', class: p === pct ? 'on' : '', onclick: (ev) => {
86	        pct = p;
87	        for (const b of seg.querySelectorAll('button')) b.classList.toggle('on', b.textContent === p);
88	        refeedLatency();
89	      } }, p)));
90	    latHead.head.append(seg);
91	
92	    const errSeries = [];
93	    for (const t of targets) errSeries.push({ label: `${t.name} err`, color: targetColor(t.id) });
94	    for (const t of targets) errSeries.push({ label: `${t.name} cas`, color: targetColor(t.id), dash: [5, 5] });
95	    charts.err = mk('Errors & contention', 'failures/s (solid) and CAS rejections/s (dashed)',
96	      { series: errSeries, unit: fmtNum, bands }).chart;
97	  }
98	
