import "testing"

// A malformed Last-Event-ID can parse to a negative number; subscribe must not
// index the event slice negatively (which would panic the SSE handler).
func TestSubscribeNegativeAfter(t *testing.T) {
	l := newEventLog()
	l.emit("hello", nil)
